SELECT COUNT(*)
FROM worker
WHERE worker_no = #{workerNo}

SELECT COUNT(*)
FROM worker
WHERE email = #{email}

mapper.update:
UPDATE worker
SET
	name = #{name},
	email = #{email}
WHERE id = #{id}

UPDATE work_time
SET
	check_in = #{checkIn},
	check_out = #{checkOut}
WHERE id = #{id}

mapper.select:
SELECT w.worker_no AS workerNo, w.name AS workerName, wt.id AS workTimeId, wt.check_date AS checkDate, wt.check_in AS checkIn, wt.check_out AS checkOut, bt.break_start AS breakStart, bt.break_end AS breakEnd FROM work_time wt
JOIN worker w ON wt.worker_id = w.id LEFT JOIN break_time bt ON bt.work_time_id = wt.id WHERE wt.check_date = #{checkDate} AND w.worker_no = #{workerNo}
ORDER BY wt.check_date DESC, wt.check_in DESC
